package io.busystack.busydata.metadata;

import io.busystack.busydata.protocol.*;
import io.busystack.busydata.sessions.SessionRegistry;
import java.sql.*;
import java.util.*;

/** Native column attributes supplement, rather than replace, exact JDBC transport types. */
public final class ColumnMetadataReader {
    private ColumnMetadataReader(){}
    public static void preflight(SessionRegistry.Session session,String schema,String table)throws SQLException {
        boolean pg=session.profile.getEngine()==Engine.POSTGRESQL;
        String sql=pg?"SELECT COALESCE(SUM(OCTET_LENGTH(pg_get_expr(d.adbin,d.adrelid))),0),COALESCE(MAX(OCTET_LENGTH(pg_get_expr(d.adbin,d.adrelid))),0),COALESCE(SUM(OCTET_LENGTH(format_type(a.atttypid,a.atttypmod))),0),COALESCE(MAX(OCTET_LENGTH(format_type(a.atttypid,a.atttypmod))),0) FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_class t ON t.oid=a.attrelid JOIN pg_catalog.pg_namespace n ON n.oid=t.relnamespace LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname=? AND t.relname=? AND a.attnum>0 AND NOT a.attisdropped":
            "SELECT COALESCE(SUM(OCTET_LENGTH(GENERATION_EXPRESSION)),0),COALESCE(MAX(OCTET_LENGTH(GENERATION_EXPRESSION)),0),COALESCE(SUM(OCTET_LENGTH(COLUMN_TYPE)),0),COALESCE(MAX(OCTET_LENGTH(COLUMN_TYPE)),0),COUNT(*),COALESCE(SUM(OCTET_LENGTH(COLUMN_DEFAULT)),0),COALESCE(MAX(OCTET_LENGTH(COLUMN_DEFAULT)),0) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY ? AND BINARY TABLE_NAME=BINARY ?";
        try(var statement=session.adapter.catalogStatement(session.connection,sql)){statement.setString(1,schema);statement.setString(2,table);try(var rows=statement.executeQuery()){if(!rows.next())throw new SQLException("Native column resource inspection unavailable");if(rows.getLong(1)>4_194_304||rows.getLong(2)>65_536||rows.getLong(3)>1_048_576||rows.getLong(4)>65_536)throw new IllegalArgumentException("Native column declarations exceed their JDBC byte budget");if(!pg&&(rows.getLong(5)>2048||rows.getLong(6)>4_194_304||rows.getLong(7)>1_048_576))throw new IllegalArgumentException("Native column defaults exceed their JDBC byte/column budget");}}
    }
    public static List<SchemaObject> enrich(SessionRegistry.Session session,List<SchemaObject> columns,String schema,String table)throws SQLException {
        return enrich(session,columns,schema,table,ignored->{});
    }
    /** Same reader; scoped acquisitions may account each bounded native row before retention. */
    public static List<SchemaObject> enrich(SessionRegistry.Session session,List<SchemaObject> columns,String schema,String table,java.util.function.LongConsumer allocations)throws SQLException {
        boolean pg=session.profile.getEngine()==Engine.POSTGRESQL;
        String sql=pg?"SELECT a.attname name,a.attrelid::text||':'||a.attnum::text native_id,a.attrelid::text parent_native_id,format_type(a.atttypid,a.atttypmod) native_type,typ.oid::text native_type_id,typ.typtype::text native_type_kind,CASE WHEN typ.typtype='d' THEN format_type(typ.typbasetype,typ.typtypmod) ELSE '' END domain_base_type,typ.typcategory::text category,a.attndims dimensions,COALESCE(en.nspname,'') array_element_schema,COALESCE(element.typname,'') array_element_type,COALESCE(element.oid::text,'') array_element_type_id,COALESCE(element.typdelim::text,'') array_element_delimiter,COALESCE(element.typtype::text,'') array_element_kind,COALESCE(element.typcategory::text,'') array_element_category,CASE WHEN element.typtype='d' THEN format_type(element.typbasetype,element.typtypmod) ELSE '' END array_element_base_type,COALESCE(bn.nspname,'') array_element_base_schema,COALESCE(base.typname,'') array_element_base_name,a.attgenerated::text generated_kind,a.attidentity::text identity_kind,CASE WHEN a.attgenerated<>'' THEN COALESCE(pg_get_expr(d.adbin,d.adrelid),'') ELSE '' END generation_expression,COALESCE(coll.collname,'') collation,CASE WHEN OCTET_LENGTH(col_description(t.oid,a.attnum))<=8192 THEN col_description(t.oid,a.attnum) ELSE NULL END remarks,COALESCE(OCTET_LENGTH(col_description(t.oid,a.attnum)),0) remarks_bytes FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_class t ON t.oid=a.attrelid JOIN pg_catalog.pg_namespace n ON n.oid=t.relnamespace JOIN pg_catalog.pg_type typ ON typ.oid=a.atttypid LEFT JOIN pg_catalog.pg_type element ON element.oid=typ.typelem LEFT JOIN pg_catalog.pg_namespace en ON en.oid=element.typnamespace LEFT JOIN pg_catalog.pg_type base ON base.oid=element.typbasetype LEFT JOIN pg_catalog.pg_namespace bn ON bn.oid=base.typnamespace LEFT JOIN pg_catalog.pg_collation coll ON coll.oid=a.attcollation LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname=? AND t.relname=? AND a.attnum>0 AND NOT a.attisdropped":
            "SELECT COLUMN_NAME name,'' native_id,'' parent_native_id,COLUMN_TYPE native_type,'' native_type_id,DATA_TYPE native_type_kind,'' domain_base_type,DATA_TYPE category,0 dimensions,'' array_element_schema,'' array_element_type,'' array_element_type_id,'' array_element_delimiter,'' array_element_kind,'' array_element_category,'' array_element_base_type,'' array_element_base_schema,'' array_element_base_name,EXTRA generated_kind,CASE WHEN EXTRA LIKE '%auto_increment%' THEN 'AUTO_INCREMENT' ELSE '' END identity_kind,COALESCE(GENERATION_EXPRESSION,'') generation_expression,COALESCE(COLLATION_NAME,'') collation,CASE WHEN OCTET_LENGTH(COLUMN_COMMENT)<=8192 THEN COLUMN_COMMENT ELSE NULL END remarks,OCTET_LENGTH(COLUMN_COMMENT) remarks_bytes FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY ? AND BINARY TABLE_NAME=BINARY ?";
        if(pg){sql=sql.replace("format_type(a.atttypid,a.atttypmod) native_type","CASE WHEN OCTET_LENGTH(format_type(a.atttypid,a.atttypmod))<=32768 THEN format_type(a.atttypid,a.atttypmod) ELSE NULL END native_type,OCTET_LENGTH(format_type(a.atttypid,a.atttypmod)) native_type_bytes").replace("CASE WHEN a.attgenerated<>'' THEN COALESCE(pg_get_expr(d.adbin,d.adrelid),'') ELSE '' END generation_expression","CASE WHEN a.attgenerated<>'' AND OCTET_LENGTH(pg_get_expr(d.adbin,d.adrelid))<=8192 THEN COALESCE(pg_get_expr(d.adbin,d.adrelid),'') ELSE '' END generation_expression,CASE WHEN a.attgenerated<>'' THEN COALESCE(OCTET_LENGTH(pg_get_expr(d.adbin,d.adrelid)),0) ELSE 0 END generation_expression_bytes");}
        else sql=sql.replace("COLUMN_TYPE native_type","CASE WHEN OCTET_LENGTH(COLUMN_TYPE)<=32768 THEN COLUMN_TYPE ELSE NULL END native_type,OCTET_LENGTH(COLUMN_TYPE) native_type_bytes").replace("COALESCE(GENERATION_EXPRESSION,'') generation_expression","CASE WHEN OCTET_LENGTH(GENERATION_EXPRESSION)<=8192 THEN COALESCE(GENERATION_EXPRESSION,'') ELSE '' END generation_expression,OCTET_LENGTH(GENERATION_EXPRESSION) generation_expression_bytes");
        if(pg)sql=sql.replace("remarks_bytes FROM pg_catalog.pg_attribute","remarks_bytes,CASE WHEN COALESCE(column_base.typname,typ.typname) IN ('time','timetz','timestamp','timestamptz') THEN CASE WHEN COALESCE(NULLIF(a.atttypmod,-1),typ.typtypmod)<0 THEN 6 ELSE COALESCE(NULLIF(a.atttypmod,-1),typ.typtypmod) END ELSE NULL END temporal_precision FROM pg_catalog.pg_attribute").replace("LEFT JOIN pg_catalog.pg_type element","LEFT JOIN pg_catalog.pg_type column_base ON column_base.oid=typ.typbasetype LEFT JOIN pg_catalog.pg_type element");
        else sql=sql.replace("remarks_bytes FROM information_schema.COLUMNS","remarks_bytes,COLUMN_DEFAULT jdbc_default,IS_NULLABLE jdbc_nullable,ORDINAL_POSITION jdbc_ordinal,DATETIME_PRECISION temporal_precision FROM information_schema.COLUMNS");
        var details=new HashMap<String,Map<String,String>>();
        try(var statement=session.adapter.catalogStatement(session.connection,sql)) {
            statement.setString(1,schema);statement.setString(2,table);
            try(var rows=statement.executeQuery()){while(rows.next()) {
                if(details.size()>=2048)throw new IllegalArgumentException("Native column metadata budget exceeded");
                var properties=new HashMap<String,String>();
                for(String field:List.of("native_id","parent_native_id","native_type","native_type_id","native_type_kind","domain_base_type","category","dimensions","array_element_schema","array_element_type","array_element_type_id","array_element_delimiter","array_element_kind","array_element_category","array_element_base_type","array_element_base_schema","array_element_base_name","generated_kind","identity_kind","generation_expression","collation","remarks"))properties.put(switch(field){case "native_id"->"nativeId";case "parent_native_id"->"parentNativeId";case "native_type"->"type";case "native_type_id"->"nativeTypeId";case "native_type_kind"->"nativeTypeKind";case "domain_base_type"->"domainBaseType";case "generated_kind"->"generatedKind";case "identity_kind"->"identityKind";case "generation_expression"->"generationExpression";case "array_element_schema"->"arrayElementSchema";case "array_element_type"->"arrayElementType";case "array_element_type_id"->"arrayElementTypeId";case "array_element_delimiter"->"arrayElementDelimiter";case "array_element_kind"->"arrayElementKind";case "array_element_category"->"arrayElementCategory";case "array_element_base_type"->"arrayElementBaseType";case "array_element_base_schema"->"arrayElementBaseSchema";case "array_element_base_name"->"arrayElementBaseName";default->field;},Objects.toString(rows.getString(field),""));
                if(pg&&!properties.get("arrayElementType").isEmpty())properties.put("verifiedQualifiedElementType",session.adapter.quote(properties.get("arrayElementSchema"))+"."+session.adapter.quote(properties.get("arrayElementType")));
                properties.put("remarksAvailability",rows.getLong("remarks_bytes")>8192?"LIMITED":"AVAILABLE");
                properties.put("nativeTypeAvailability",rows.getLong("native_type_bytes")>32768?"LIMITED":"AVAILABLE");
                properties.put("generationExpressionAvailability",rows.getLong("generation_expression_bytes")>8192?"LIMITED":"AVAILABLE");
                String temporalPrecision=rows.getString("temporal_precision");
                if(temporalPrecision!=null){int precision=Integer.parseInt(temporalPrecision);if(precision<0||precision>6)throw new SQLException("Native temporal precision is outside the verified engine range");properties.put("scale",temporalPrecision);properties.put("nativeTemporalPrecision",temporalPrecision);}
                if(!pg){String nativeType=properties.get("type").toUpperCase(Locale.ROOT);properties.put("unsigned",Boolean.toString(nativeType.contains(" UNSIGNED")));String defaultValue=rows.getString("jdbc_default");properties.put("default",Objects.toString(defaultValue,""));properties.put("defaultAvailability",defaultValue==null?"ABSENT":"AVAILABLE");properties.put("nullable",Objects.toString(rows.getString("jdbc_nullable"),"UNKNOWN"));properties.put("ordinal",Integer.toString(rows.getInt("jdbc_ordinal")));properties.put("generated",rows.getLong("generation_expression_bytes")>0?"YES":"NO");properties.put("autoIncrement",properties.get("identityKind").isEmpty()?"NO":"YES");}
                long allocation=512L+128L*properties.size();for(var property:properties.entrySet())allocation+=4L*(property.getKey().length()+property.getValue().length());
                allocations.accept(allocation);details.put(rows.getString("name"),Map.copyOf(properties));
            }}
        }
        var result=new ArrayList<SchemaObject>();
        for(var column:columns){var properties=details.get(column.getName());if(properties==null)throw new SQLException("Native column identity changed during introspection");allocations.accept(512L+4L*column.getSerializedSize()+128L*properties.size());result.add(column.toBuilder().putAllProperties(properties).build());}
        return List.copyOf(result);
    }
}
